import os

# Search for tched as parts of words: prefix-tched, tched-suffix, etc.
# Also check for substrings like 'atched', 'itched', 'etched', 'atch ed', etc.
target_bytes = b'tched'

for root, dirs, files in os.walk('crates/op-assistant-grpc'):
    for fname in sorted(files):
        path = os.path.join(root, fname)
        with open(path, 'rb') as f:
            data = f.read()

        # Check for tched embedded in longer byte sequences that aren't split
        idx = 0
        while True:
            idx = data.find(target_bytes, idx)
            if idx == -1:
                break

            # Get the full word boundary
            start = idx
            while start > 0 and data[start-1:start] not in (b' ', b'\n', b'\t', b'.', b',', b';', b':', b'(', b')', b'[', b']', b'{', b'}', b'|', b'=', b'+', b'-', b'_', b'/', b'\"', b\"'\", b'>', b'<', b'!', b'?', b'&', b'*', b'@', b'#', b'%', b'\$'):
                start -= 1

            end = idx + len(target_bytes)
            while end < len(data) and data[end:end+1] not in (b' ', b'\n', b'\t', b'.', b',', b';', b':', b'(', b')', b'[', b']', b'{', b'}', b'|', b'=', b'+', b'-', b'_', b'/', b'\"', b\"'\", b'>', b'<', b'!', b'?', b'&', b'*', b'@', b'#', b'%', b'\$'):
