target = 'tched'
target_bytes = target.encode('ascii')

for root, dirs, files in os.walk('crates/op-assistant-grpc'):
    for fname in sorted(files):
        path = os.path.join(root, fname)
        with open(path, 'rb') as f:
            data = f.read()

        # Check base64 encoded versions of "tched"
        encoded_variants = [
            base64.b64encode(target_bytes),  # dGNoZWQ=
            base64.b64encode(target_bytes).decode(),
        ]

        # Also check for tched split into parts
        for m in re.finditer(rb'[A-Za-z0-9+/]{8,}={0,2}', data):
            chunk = m.group(0)
            try:
                decoded = base64.b64decode(chunk)
                if b'tched' in decoded:
                    print(f"BASE64 ENCODED in {path}: {chunk} -> contains tched")
            except:
                pass

print("Base64 scan complete")

